# inspect all 3x3 windows for dominant-color occupancy counts and binary patterns for demo2
for r in range(5):
 for c in range(5):
  w=[[d2[i+r][j+c] for j in range(3)] for i in range(3)]
  if sum(x==2 for row in w for x in row)>=3: print(r,c, ''.join(''.join('X' if x==2 else '.' for x in row)+'/' for row in w))

def transposes(m):
 out=[]
 for k in range(4):
  x=[list(row) for row in m]
  for _ in range(k): x=[list(row) for row in zip(*x[::-1])]
  out.append(x); out.append([row[::-1] for row in x])
 return out
def best(grid, target, val):
 bests=[]
 for r in range(5):
  for c in range(5):
   m=[[int(grid[i+r][j+c]==val) for j in range(3)] for i in range(3)]
   for t in transposes(target):
    score=sum(m[i][j]==t[i][j] for i in range(3) for j in range(3))
    bests.append((score,r,c,m,t))
 return sorted(bests,reverse=True,key=lambda x:x[0])[:3]
print('d3',best(d3,pat3,3))

