def exact_any(g,pat,val):
 ret=[]
 for k,t in enumerate(transposes(pat)):
  for r in range(5):
   for c in range(5):
    w=[[int(g[r+i][c+j]==val) for j in range(3)] for i in range(3)]
    if w==t: ret.append((r,c,k))
 return ret
